// Format the RAG API response for chat display
const response = $input.first().json;

let output = response.response || 'No response received';

// Add confidence indicator if available
if (response.confidence && response.confidence > 0) {
  const confidencePercent = Math.round(response.confidence * 100);
  const emoji = confidencePercent >= 80 ? '🎯' : confidencePercent >= 60 ? '📊' : '🔍';
  output += `\n\n${emoji} Confidence: ${confidencePercent}%`;
}

// Add source attribution
if (response.sources && response.sources.length > 0) {
  output += `\n📖 Source: Alice in Wonderland`;
}

// Handle errors gracefully
if (response.error) {
  output = `⚠️ ${response.response}\n\nPlease try rephrasing your question or check if the RAG API is running.`;
}

return {
  json: {
    output: output
  }
};
